/* --------------------------------------------------------------------------
   Rules the node-style whitelist cannot express, pinned to node ids (stable
   across dashboard edits). Each one names why it is here.
   -------------------------------------------------------------------------- */

/* Back-to-top is viewport-fixed; `position: fixed` is off the whitelist. */
[data-bz-node="totop-holder"]{position:fixed;bottom:24px;right:24px;z-index:60;width:auto;padding:0}
[data-bz-node="totop-holder"] .bz-row{display:block}
[data-bz-node="totop"] .bz-btns{margin:0}
[data-bz-node="totop"] .bz-btn{border-radius:var(--radius-chip);box-shadow:0 8px 20px rgba(0,0,0,.2)}

/* Hero scrim is a 90deg gradient; `background` accepts a flat colour only. */
[data-bz-node="hero"]{position:relative}
[data-bz-node="hero"]::before{content:"";position:absolute;inset:0;z-index:0;pointer-events:none;
  background:linear-gradient(90deg,rgba(26,23,20,.9) 0%,rgba(26,23,20,.6) 45%,rgba(26,23,20,.3) 100%)}
[data-bz-node="hero"] > *{position:relative;z-index:1}

/* The eyebrow pill is a node; its inner <p> carries the block's default margin. */
/* `.bz-block p` sets font-size/line-height on the paragraph itself, which beats
   anything the node style puts on the block wrapper. Typography for a `text`
   block therefore has to be stated against the paragraph. */
[data-bz-node="hero-eyebrow"] p{margin:0;font-size:13px;line-height:1.2;letter-spacing:.06em}
[data-bz-node="hero-sub"] p{margin:0;font-size:18px;line-height:1.6}
[data-bz-node="hero-h"] h1{line-height:1.05;letter-spacing:0}

/* Hero search: white card with the handoff's shadow. The widget owns the markup. */
[data-bz-node="hero-search"] .bz-searchbar{background:#fff;border-radius:var(--radius-input);
  overflow:hidden;box-shadow:0 12px 32px rgba(0,0,0,.25);gap:0;flex-wrap:nowrap}
[data-bz-node="hero-search"] .bz-searchbar .bz-input{border:0;border-radius:0;padding:16px 18px;
  font-size:15px;line-height:1.2;background:transparent;min-width:0}
[data-bz-node="hero-search"] .bz-searchbar .bz-btn{border-radius:0;padding:0 24px;white-space:nowrap;
  font-family:var(--font-heading);font-weight:700;font-size:15px}

/* Decorative ▲ beside the wordmark — kept in CSS so it has no accessible name. */
[data-bz-node="logo"] .bz-brand{display:inline-flex;align-items:center}
[data-bz-node="logo"] .bz-brand::before{content:"";flex:0 0 auto;
  width:20px;height:18px;background:url("/icons/mark-triangle.svg") no-repeat center/contain}

/* Nav dropdown caret: the menu block draws none for items with children. */
[data-bz-node="main-nav"] .bz-navitem--has-sub > a::after{content:"";display:inline-block;
  margin-left:6px;border:4px solid transparent;border-top-color:currentColor;transform:translateY(2px)}

/* The search glyph is the last nav item, so it sits inside the pill. Its label
   stays in the DOM as the accessible name and is swapped for the icon. */
[data-bz-node="main-nav"] .bz-navitem:last-child > a{width:32px;height:32px;padding:0;overflow:hidden;
  text-indent:-999px;background:url("/icons/search.svg") no-repeat center/16px 16px;margin-left:4px}

/* `fontFamily` is not on the style whitelist, and "INTL Headline" is an
   all-caps display face. Nav links default to it, so anything the handoff sets
   in mixed case has to be moved back to the body family here. */
[data-bz-node="utility-phone"] .bz-navitem > a,
[data-bz-node="utility-nav"] .bz-navitem > a{font-family:var(--font-body);font-size:14px;
  line-height:1.35;padding-block:0}
[data-bz-node="utility-phone"] .bz-nav{gap:14px}
[data-bz-node="utility-nav"] .bz-nav{gap:28px}

/* Utility glyphs — decorative, so CSS rather than nodes keeps them out of the
   accessible name. */
[data-bz-node="utility-phone"] .bz-navitem:first-child > a::before{content:"\260E";margin-right:8px;font-size:15px}
[data-bz-node="utility-nav"] .bz-navitem:last-child > a::before{content:"\25CE";margin-right:6px;font-size:14px}
[data-bz-node="utility-nav"] .bz-navitem:last-child > a::after{content:"\25BE";margin-left:6px;font-size:10px}

/* Main nav: the handoff's 12.5px body-font item with 8px/9px padding. */
[data-bz-node="main-nav"] .bz-navitem > a{font-family:var(--font-body);font-size:12.5px;
  font-weight:700;letter-spacing:.125px;line-height:1.28;padding:8px 9px}
[data-bz-node="main-nav"] .bz-nav{gap:0}
[data-bz-node="logo"] .bz-brand{font-size:19px;line-height:1.2;letter-spacing:.3px;gap:10px}

/* Quick-link cells: dividers and the hover the handoff specifies. */
[data-bz-node="quick-card"]{box-shadow:0 16px 40px rgba(0,0,0,.1)}
[data-bz-node="quick-card"] > .bz-col{border-right:1px solid var(--line)}
[data-bz-node="quick-card"] > .bz-col:last-child{border-right:0}

/* .bz-btns carries margin-block:var(--space-5); the nav glyph must not. */
[data-bz-node="nav-search"] .bz-btns{margin-block:0;gap:0;align-items:center}
/* Utility bar sits at the handoff's 39px: 10px padding either side of a 19px row. */
[data-bz-node="utility-phone"] .bz-nav,[data-bz-node="utility-nav"] .bz-nav,
[data-bz-node="utility-phone"] .bz-navitem,[data-bz-node="utility-nav"] .bz-navitem{line-height:1.35;align-items:center}

/* blocks.css hardcodes padding-inline:var(--space-4) on a section's container,
   which overrides the --container-pad the token layer emits. The handoff pads
   the grid 24px, so restore the token here. */
.bz-section > .bz-container{padding-inline:var(--container-pad,16px)}
@media (max-width:1100px){.bz-section > .bz-container{padding-inline:var(--container-pad-tablet,var(--container-pad,16px))}}
@media (max-width:640px){.bz-section > .bz-container{padding-inline:var(--container-pad-mobile,var(--container-pad,16px))}}

/* ---- Back-to-top: a 46px accent disc with an arrow, not a labelled button. */
[data-bz-node="totop"] .bz-btn{position:relative;width:46px;height:46px;padding:0;border-radius:999px;
  overflow:hidden;text-indent:-999px;background:var(--accent);color:var(--ink);border:0}
[data-bz-node="totop"] .bz-btn::after{content:"\2191";position:absolute;inset:0;display:flex;
  align-items:center;justify-content:center;text-indent:0;font-size:18px;color:var(--ink)}

/* ---- Ink-filled CTAs. The renderer offers accent / white / link only, and the
   handoff puts an ink button on the service, parts and financing bands. */
[data-bz-node="financing-cta"] .bz-btn,
[data-bz-node="service-cta"] .bz-btn,
[data-bz-node="parts-cta"] .bz-btn{background:var(--ink);color:#F2EEE6;border-color:var(--ink)}
[data-bz-node="financing-cta"] .bz-btn:hover,
[data-bz-node="service-cta"] .bz-btn:hover,
[data-bz-node="parts-cta"] .bz-btn:hover{background:#000;border-color:#000}
[data-bz-node="financing-cta"] .bz-btn{min-height:48px;padding:0 26px;font-size:15px}
[data-bz-node="service-cta"] .bz-btn,
[data-bz-node="parts-cta"] .bz-btn{min-height:46px;padding:0 22px;font-size:14px}

/* ---- Testimonial controls: 40px outlined discs with chevrons. */
[data-bz-node="quotes-prev"] .bz-btn,[data-bz-node="quotes-next"] .bz-btn{position:relative;
  width:40px;height:40px;padding:0;border-radius:999px;overflow:hidden;text-indent:-999px;
  background:var(--card);border:1.5px solid var(--line);color:var(--ink)}
[data-bz-node="quotes-prev"] .bz-btn::after,[data-bz-node="quotes-next"] .bz-btn::after{
  position:absolute;inset:0;display:flex;align-items:center;justify-content:center;
  text-indent:0;font-size:16px;color:var(--ink)}
[data-bz-node="quotes-prev"] .bz-btn::after{content:"\2039"}
[data-bz-node="quotes-next"] .bz-btn::after{content:"\203A"}
[data-bz-node="quotes-prev"] .bz-btns,[data-bz-node="quotes-next"] .bz-btns{margin-block:0;justify-content:center}

/* ---- Blog cards carry a category and title only in the handoff. */
[data-bz-node="blog-list"] .bz-post__d{display:none}
[data-bz-node="blog-list"] .bz-card__t{font-family:var(--font-heading);font-weight:700;font-size:17px;
  line-height:1.4;text-transform:uppercase}
[data-bz-node="blog-list"] .bz-card{border-radius:var(--radius-card);overflow:hidden;background:#fff}
[data-bz-node="blog-list"] .bz-card__body{padding:20px 22px 24px}
[data-bz-node="blog-list"] .bz-card img{aspect-ratio:16/10;object-fit:cover}

/* ---- Brand coverflow -----------------------------------------------------
   The handoff stages five cards in 3D. Node styles carry translateX/Y, scale
   and a 2D rotate only, so perspective / rotateY / translateZ live here and
   the active index is driven by custom.js below. */
[data-bz-node="brands-rail"]{position:relative;perspective:1800px;cursor:grab;user-select:none;
  overflow:visible!important}
[data-bz-node="brands-rail"].is-dragging{cursor:grabbing}
[data-bz-node="brands-rail"] > .bz-col{
  position:absolute;width:340px;aspect-ratio:1/1;
  background:repeating-linear-gradient(135deg,#EDE7DA,#EDE7DA 12px,#E1DACB 12px,#E1DACB 24px);
  border-radius:var(--radius-card);padding-bottom:70px;
  transition:transform .35s ease,opacity .35s ease;will-change:transform}
[data-bz-node="brands-rail"] > .bz-col::after{content:"Brand hero image";font-family:var(--font-body);
  font-size:11px;letter-spacing:.1em;color:var(--color-muted,var(--muted));text-transform:uppercase;
  order:2;margin-top:-4px}
[data-bz-node="brands-rail"] > .bz-col h3{font-size:26px;line-height:1.15;max-width:80%;order:1}

[data-bz-node="brands-rail"] > .bz-col[data-pos="0"]{transform:translateX(0) translateZ(0) rotateY(0deg) scale(1.25);
  opacity:1;z-index:5;box-shadow:0 28px 60px rgba(0,0,0,.22)}
[data-bz-node="brands-rail"] > .bz-col[data-pos="-1"]{transform:translateX(-400px) translateZ(-160px) rotateY(35deg) scale(.82);
  opacity:.7;z-index:4;box-shadow:0 8px 18px rgba(0,0,0,.1)}
[data-bz-node="brands-rail"] > .bz-col[data-pos="1"]{transform:translateX(400px) translateZ(-160px) rotateY(-35deg) scale(.82);
  opacity:.7;z-index:4;box-shadow:0 8px 18px rgba(0,0,0,.1)}
[data-bz-node="brands-rail"] > .bz-col[data-pos="-2"]{transform:translateX(-610px) translateZ(-320px) rotateY(45deg) scale(.62);
  opacity:.4;z-index:3;box-shadow:0 8px 18px rgba(0,0,0,.1)}
[data-bz-node="brands-rail"] > .bz-col[data-pos="2"]{transform:translateX(610px) translateZ(-320px) rotateY(-45deg) scale(.62);
  opacity:.4;z-index:3;box-shadow:0 8px 18px rgba(0,0,0,.1)}

/* Only the front card offers the CTA, as in the handoff. */
[data-bz-node="brands-rail"] > .bz-col .bz-btns{order:3;position:absolute;bottom:24px;left:50%;
  transform:translateX(-50%);margin:0;opacity:0;pointer-events:none;transition:opacity .35s ease}
[data-bz-node="brands-rail"] > .bz-col[data-pos="0"] .bz-btns{opacity:1;pointer-events:auto}
[data-bz-node="brands-rail"] > .bz-col .bz-btn{white-space:nowrap;padding:13px 24px;font-size:15px}
[data-bz-node="brands-rail"] > .bz-col .bz-btn::after{content:" \2192";margin-left:8px}
[data-bz-node="brands-controls"]{display:flex;justify-content:center;gap:14px}
[data-bz-node="brands-controls"] > .bz-col{flex:0 0 44px;width:44px}

/* 44px outlined discs, matching the handoff's arrows. */
[data-bz-node="brands-prev"] .bz-btn,[data-bz-node="brands-next"] .bz-btn{position:relative;
  width:44px;height:44px;padding:0;border-radius:999px;overflow:hidden;text-indent:-999px;
  background:var(--card);border:1.5px solid var(--line);color:var(--ink)}
[data-bz-node="brands-prev"] .bz-btn::after,[data-bz-node="brands-next"] .bz-btn::after{
  position:absolute;inset:0;display:flex;align-items:center;justify-content:center;text-indent:0;font-size:16px}
[data-bz-node="brands-prev"] .bz-btn::after{content:"\2039"}
[data-bz-node="brands-next"] .bz-btn::after{content:"\203A"}
[data-bz-node="brands-prev"] .bz-btns,[data-bz-node="brands-next"] .bz-btns{margin-block:0;justify-content:center}
[data-bz-node="brands-controls"]{gap:14px;justify-content:center}

/* ---- Forms. The renderer wraps a form in a bordered card with a heading and
   visible labels; the handoff shows neither. Labels stay in the DOM as the
   accessible name and are visually hidden, so placeholder-only styling does
   not cost screen-reader users the field name. */
[data-bz-node="contact-form"] .bz-form,[data-bz-node="newsletter-form"] .bz-form{
  background:none;border:0;border-radius:0;padding:0;gap:12px;max-width:440px}
[data-bz-node="contact-form"] .bz-form__t,[data-bz-node="newsletter-form"] .bz-form__t{display:none}
[data-bz-node="contact-form"] .bz-label,[data-bz-node="newsletter-form"] .bz-label{
  position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
[data-bz-node="contact-form"] .bz-input,[data-bz-node="contact-form"] textarea{
  min-height:46px;padding:0 16px;border:1.5px solid var(--line);border-radius:var(--radius-input);
  font-size:14px;background:var(--card)}
[data-bz-node="contact-form"] textarea{padding:13px 16px;min-height:112px}
[data-bz-node="contact-form"] .bz-btn{min-height:48px;font-size:15px}

/* Newsletter is a single inline row with an ink button. */
[data-bz-node="newsletter-form"] .bz-form{flex-direction:row;flex-wrap:wrap;gap:8px;
  align-items:flex-start;max-width:none}
[data-bz-node="newsletter-form"] .bz-field{flex:1 1 180px;min-width:180px}
[data-bz-node="newsletter-form"] .bz-input{min-height:44px;padding:0 14px;
  border:1.5px solid var(--line);border-radius:var(--radius-input);font-size:14px;background:var(--card)}
[data-bz-node="newsletter-form"] .bz-btn{min-height:44px;padding:0 20px;background:var(--ink);
  color:#F2EEE6;border-color:var(--ink);font-size:14px}
/* DOM order is field, consent, button; the handoff puts the button beside the
   input, so reorder rather than move the consent out of the form. */
[data-bz-node="newsletter-form"] .bz-field{order:1}
[data-bz-node="newsletter-form"] .bz-btn{order:2}
[data-bz-node="newsletter-form"] .bz-field--consent{order:3;flex:1 1 100%;min-width:0}
[data-bz-node="newsletter-form"] .bz-form__status{order:4;flex:1 1 100%}
[data-bz-node="contact-h"] h2{font-size:32px}
[data-bz-node="newsletter-h"] h3{font-size:20px}

