/* Brand coverflow: the active-index state the handoff's 3D stage needs.
   Kept here because a custom widget may not carry <script> and the renderer's
   carousel behaviour scrolls a flat rail instead of staging cards in depth. */
(function () {
  var rail = document.querySelector('[data-bz-node="brands-rail"]');
  if (!rail) return;
  var cards = Array.prototype.slice.call(rail.children);
  if (cards.length < 2) return;
  var n = cards.length, active = 0, dragFrom = null;

  function paint() {
    cards.forEach(function (card, i) {
      var offset = (i - active + n) % n;
      if (offset > Math.floor(n / 2)) offset -= n;
      card.setAttribute('data-pos', String(offset));
      card.setAttribute('aria-hidden', offset === 0 ? 'false' : 'true');
      var cta = card.querySelector('a,button');
      if (cta) cta.tabIndex = offset === 0 ? 0 : -1;
    });
  }
  function go(step) { active = (active + step + n) % n; paint(); }

  cards.forEach(function (card, i) {
    card.addEventListener('click', function (e) {
      if (Number(card.getAttribute('data-pos')) === 0) return;   // front card keeps its CTA
      e.preventDefault();
      active = i; paint();
    });
  });

  function bind(sel, step) {
    var el = document.querySelector(sel + ' a, ' + sel + ' button');
    if (el) el.addEventListener('click', function (e) { e.preventDefault(); go(step); });
  }
  bind('[data-bz-node="brands-prev"]', -1);
  bind('[data-bz-node="brands-next"]', 1);

  function startX(e) { return e.touches ? e.touches[0].clientX : e.clientX; }
  rail.addEventListener('mousedown', function (e) { dragFrom = startX(e); rail.classList.add('is-dragging'); });
  rail.addEventListener('touchstart', function (e) { dragFrom = startX(e); }, { passive: true });
  function end(e) {
    if (dragFrom === null) return;
    var x = e.changedTouches ? e.changedTouches[0].clientX : e.clientX;
    var delta = x - dragFrom;
    dragFrom = null; rail.classList.remove('is-dragging');
    if (delta > 40) go(-1); else if (delta < -40) go(1);        // handoff's 40px threshold
  }
  rail.addEventListener('mouseup', end);
  rail.addEventListener('mouseleave', end);
  rail.addEventListener('touchend', end);

  paint();
})();
